async function main() {
  console.log('Creating seed user...');
  let userId;
  const { data: existingUsers } = await sb.auth.admin.listUsers({ page: 1, perPage: 100 });
  const existing = existingUsers?.users?.find(u => u.email === 'seed-buyers@lotscout.com');

  if (existing) {
    userId = existing.id;
    console.log('Seed user exists:', userId);
  } else {
    const { data: newUser, error: createErr } = await sb.auth.admin.createUser({
      email: 'seed-buyers@lotscout.com',
      password: 'SeedBuyers2026!',
      email_confirm: true,
    });
    if (createErr) { console.error('Failed to create user:', createErr); return; }
    userId = newUser.user.id;
    console.log('Created seed user:', userId);
  }

  // Build all records
  const records = [];

  // National buyers
  for (const b of NATIONAL) {
    records.push({
      user_id: userId,
      status: 'active',
      display_name: b.display_company,
      display_company: b.display_company,
      contact_phone: b.contact_phone,
      contact_phone_type: b.contact_phone_type,
      contact_email: b.contact_email,
      contact_website: b.contact_website,
      target_state: b.target_state,
      target_regions: b.target_state ? [b.target_state] : ['National'],
      budget_min: b.budget_min,
      budget_max: b.budget_max,
      min_acreage: b.min_acreage,
      max_acreage: b.max_acreage,
      use_case: b.use_case,
      timeline: TIMELINE,
    });
  }

  // State buyers from detailed sets
  const ALL_STATE_BUYERS = { ...STATE_BUYERS, ...REMAINING_STATE_DATA };
  for (const [state, buyers] of Object.entries(ALL_STATE_BUYERS)) {
    for (const b of buyers) {
      records.push({
        user_id: userId,
        status: 'active',
        display_name: b.display_company || b.name,
        display_company: b.display_company || b.name,
        contact_phone: b.contact_phone,
        contact_phone_type: b.contact_phone_type || b.phoneType || 'General',
        contact_email: b.contact_email || b.email,
        contact_website: b.contact_website || b.website,
        target_state: state,
        target_regions: [state],
        budget_min: b.budget_min || b.budgetMin || 200000,
        budget_max: b.budget_max || b.budgetMax || 10000000,
        min_acreage: b.min_acreage || b.minAcres || 50,
        max_acreage: b.max_acreage || b.maxAcres || 5000,
        use_case: b.use_case || b.useCase || 'Mixed Use',
        timeline: TIMELINE,
      });
    }
  }

  console.log(`Inserting ${records.length} buyer records in batches...`);

  // Insert in batches of 50
  let inserted = 0;
  for (let i = 0; i < records.length; i += 50) {
    const batch = records.slice(i, i + 50);
    const { error } = await sb.from('buyer_requests').insert(batch);
    if (error) {
      console.error(`Batch ${i}-${i+50} error:`, error.message);
    } else {
      inserted += batch.length;
      process.stdout.write(`\r  Inserted ${inserted}/${records.length}...`);
    }
  }

  console.log(`\nDone! Inserted ${inserted} records.`);
}

main().catch(console.error);
